# pixal3d — generated by tools/gen_model_py.py from the yaml
# cascade (2026-09-02 flip), then hand-edited since. The
# class IS the unit: family head → variants → quant cells;
# merged_defaults() walks the cascade. Parity pinned by
# tests/walls/suites/test_python_models.py + the http goldens.
#
# SSOT law: this file REPLACES model.yaml + variants/. A
# model.yaml reappearing next to it is a LOUD refusal.
#
# Boards the img-to-mesh card as the PIXEL-ALIGNED lift: shares the
# TRELLIS.2 backbone, VAEs, DINOv3 + NAF feature-upsampler, and the
# whole sampler chain (structure → shape → upsample → texture →
# apply → bake → glb) — the only delta from trellis2-native is the
# conditioning node (Pixal3DConditioning instead of Trellis2Conditioning,
# which carries a proj_pack + camera transform) and a MoGe depth pass
# for per-image FOV. See docs/design/img-to-mesh-pixal3d-boarding.md
# (2026-09, Status: landed) and docs/research/trellis2-native-method-case-study.md
# §2 (M4 — the conditioning-node swap is the entire model delta).


from melite_models import  KnobRow,Model, Variant, Cell, LoraRow, Provision, LaneInputs, Studio, StudioKind, Genre

# The Pixal3D weight set (Phase P, 2026-09-05: Pixal3D boards the
# img-to-mesh card alongside trellis2-native). Files pinned from HF
# Comfy-Org/Pixal3D tree listings (lfs oid = sha256). PYTHON SHAPE LAW
# rung 4: a download place states url+sha+size, all-or-nothing.
#
# Pixal3D shares the Trellis2 VAEs + its own int8 ConvRot unet + the
# dino_v3_L with NAF feature-upsampler (a separate weight from the
# trellis2-native dino_v3_vit_l — the NAF module lives under the
# 'naf.' prefix inside the safetensors, popped at load into its own
# CoreModelPatcher, per docs/research/trellis2-native-method-case-study.md
# §1.3 line 115). Background removal (birefnet) is shared with
# trellis2-native.
_PIXAL3D_PROVISIONS = (
    Provision(
        name='pixal3d_int8_convrot.safetensors',
        url='https://huggingface.co/Comfy-Org/Pixal3D/resolve/main/diffusion_models/pixal3d_int8_convrot.safetensors',
        folder='diffusion_models',
        sha256='4621eac3b715484f79303c7152af641fe0b2b14f4d0e3d394fd6922d00f955ec',
        size_bytes=5584555824,
    ),
    # bf16 + multiview variants are ROUTES, not artifacts (the int8
    # ConvRot is the only weight provisioned/on disk — the cascade
    # gates the bf16/multiview cells at the variant table).
    Provision(
        name='dino_v3_L_naf_fp32.safetensors',
        url='https://huggingface.co/Comfy-Org/Pixal3D/resolve/main/clip_vision/dino_v3_L_naf_fp32.safetensors',
        folder='clip_vision',
        sha256='4ad2ec4e0879a5b5b04cd97325cc37da954a7b6edca5170b86510f17f2b2290f',
        size_bytes=1215214176,
    ),
    Provision(
        name='trellis_2_shape_vae_bf16.safetensors',
        url='https://huggingface.co/Comfy-Org/Pixal3D/resolve/main/vae/trellis_2_shape_vae_bf16.safetensors',
        folder='vae',
        sha256='de0cb4949a76c59ee5c091a995a69bcc8c51d5aeda939f0c641a50d2a72341f4',
        size_bytes=1095844024,
    ),
    Provision(
        name='trellis_2_texture_vae_bf16.safetensors',
        url='https://huggingface.co/Comfy-Org/Pixal3D/resolve/main/vae/trellis_2_texture_vae_bf16.safetensors',
        folder='vae',
        sha256='714e5ebf094a610e12a8e3b5175c18a62f37f6ea4218acb6073644456b73ab0e',
        size_bytes=948461364,
    ),
    # preprocessing (RemoveBackground) — the same birefnet weight
    # trellis2-native provisions (shared with the Pixal3D repo).
    Provision(
        name='birefnet.safetensors',
        url='https://huggingface.co/Comfy-Org/BiRefNet/resolve/main/background_removal/birefnet.safetensors',
        folder='background_removal',
        sha256='9ab37426bf4de0567af6b5d21b16151357149139362e6e8992021b8ce356a154',
        size_bytes=444473596,
    ),
    # MoGe depth model — Pixal3D's per-image FOV needs MoGe to
    # estimate the camera from the source image (camera_angle_x feeds
    # Pixal3DConditioning → camera transform matrix → per-token pixel
    # alignment). Follows the official Comfy-Org template: MoGe 2
    # (vitl, normal variant, fp16) from the Comfy-Org/MoGe repo —
    # LoadMoGeModel reads folder_paths('geometry_estimation').
    Provision(
        name='moge_2_vitl_normal_fp16.safetensors',
        url='https://huggingface.co/Comfy-Org/MoGe/resolve/main/geometry_estimation/moge_2_vitl_normal_fp16.safetensors',
        folder='geometry_estimation',
        sha256='cb1a692d03235671e959e81360d7b4d9f44aefadb1f852d6ca6aa17799d5e31f',
        size_bytes=661859924,
    ),
)




class Pixal3d(Model):
    id = 'pixal3d'
    genre = Genre.THREED
    label = 'Pixal3D'
    description = 'Pixel-aligned image → textured 3D mesh (native ComfyUI Pixal3D, MoGe camera conditioning → DINOv3+NAF pixel-aligned embeddings → shared TRELLIS.2 sampler chain → textured .glb). Hero-asset tier: nearest reconstruction fidelity, slower than TRELLIS.2.'
    # Shared img-to-mesh form (2026-09-06) — see trellis2-native: one
    # tag boards the whole card so the Model dropdown offers the lift
    # switch (TRELLIS.2 <-> Pixal3D) on the visual card.
    form = 'form_img_to_mesh'
    engine = 'comfyui'
    card = 'img-to-mesh'
    # Same studio tenant as trellis2-native — the lift-and-rig surface
    # is shared (owns_params=False: resolution/steps/cfg ride the shell;
    # writes = the card's File slots this family authors).
    studio = Studio(
        tenant='3d/img_to_mesh', owns_params=False,
        kind=StudioKind.ASSEMBLY,
        writes=(
            'input_image', 'rigged_glb', 'target_glb',
        ),
    )
    # the pixal3d stock-stack weight set (see _PIXAL3D_PROVISIONS above)
    provisions = _PIXAL3D_PROVISIONS
    # Five shared loaders + MoGe (same five weight-loads as
    # trellis2-native: unet, DINOv3, shape VAE, texture VAE,
    # birefnet — plus LoadMoGeModel on the camera_fov=auto path).
    # The MoGe weight rides the pixal3d provision row above (folder
    # = geometry_estimation; LoadMoGeModel reads from that folder);
    # the renderer references the literal name directly because
    # LaneInputs is closed (extra="forbid") and the field isn't
    # generic enough to merit a new row for one model.
    lane_inputs = LaneInputs(
        unet='pixal3d_int8_convrot.safetensors',
        vae='trellis_2_shape_vae_bf16.safetensors',
        texture_vae='trellis_2_texture_vae_bf16.safetensors',
        clip_vision='dino_v3_L_naf_fp32.safetensors',
        background_removal='birefnet.safetensors',
    )
    defaults = dict(
            resolution=1024,
            bg_removal='auto',
            steps=12,
            cfg=7.5,
            shape_steps=20,
            shape_cfg=7.5,
            tex1_steps=12,
            tex1_cfg=7.5,
            tex2_steps=12,
            tex2_cfg=1.0,
            remesh_resolution=768,
            decimate_faces=700000,
            smooth_angle=180,
            atlas_size=4096,
            ao_size=1024,
            normal_size=2048,
            struct_sampler='euler',
            struct_scheduler='normal',
            shape_sampler='euler',
            shape_scheduler='normal',
            tex1_sampler='euler',
            tex1_scheduler='simple',
            tex2_sampler='euler',
            tex2_scheduler='normal',
            sd3_shift=5.0,
            rescale_struct=0.7,
            rescale_shape=0.5,
            override_struct=0.667,
            override_shape=0.769,
            seed=42,
            camera_fov='auto',
            # NO filename_prefix (2026-09-07): the img-to-mesh surface
            # dropped the field (09-06 sweep); the run owns names now.
        )
    # the cascade as frozen rows (PYTHON SHAPE LAW rung 1). Same
    # resolution tiers as trellis2-native — the 1024/1536/512 ladder
    # covers Pixal3D's sweet spots. The multiview variants are routes
    # in the upstream Pixal3D HF repo but stay off the cascade until
    # a multiview lane is built (no multiview card, no board).
    variants = (
        Variant(id='1024', label='1024', hint='Standard resolution — DEFAULT', route='pixal3d', order=0, cells=(
                    Cell(quant='bf16', label='BF16', route='pixal3d-bf16', vram_peak_gb=12.0),
                    Cell(quant='int8', label='INT8 ConvRot', route='pixal3d-int8', vram_peak_gb=8.0),
        )),
        Variant(id='1536', label='1536', hint='Quality resolution — hero assets, final production', route='pixal3d-1536', order=2, cells=(
                    Cell(quant='bf16', label='BF16', route='pixal3d-1536-bf16', vram_peak_gb=16.0),
                    Cell(quant='int8', label='INT8 ConvRot', route='pixal3d-1536-int8', vram_peak_gb=10.0),
        )),
        Variant(id='512', label='512', hint='Fast resolution — props, thumbnails, iteration', route='pixal3d-512', order=1, cells=(
                    Cell(quant='bf16', label='BF16', route='pixal3d-512-bf16', vram_peak_gb=8.0),
                    Cell(quant='int8', label='INT8 ConvRot', route='pixal3d-512-int8', vram_peak_gb=5.0),
        )),
    )

    # the img-to-mesh card surface for the pixal arm (row 3,
    # 2026-09-06) — the trellis lift surface verbatim (the arms
    # share _shared_lift_chain; the model delta is conditioning,
    # not sampler wiring) plus camera_fov: 'auto' builds the MoGe
    # pass, a literal degree skips it — a branch directive
    # (compile row). Each arm owns its surface (the tts pair
    # precedent: parallel declarations, never cross-model imports).
    card_knobs = (
        KnobRow(card='input_image', inject='LoadImage.0.image', kind='s'),
        KnobRow(card='seed', inject='KSampler.0.seed', kind='n'),
        KnobRow(card='resolution', inject='Trellis2UpsampleStage.0.target_resolution', kind='n'),
        KnobRow(card='steps', inject='KSampler.0.steps', kind='n'),
        KnobRow(card='cfg', inject='KSampler.0.cfg', kind='n'),
        KnobRow(card='bg_removal', inject='', kind='s'),
        KnobRow(card='camera_fov', inject='', kind='s'),
        KnobRow(card='shape_steps', inject='KSampler.1.steps', kind='n'),
        KnobRow(card='shape_cfg', inject='KSampler.1.cfg', kind='n'),
        KnobRow(card='tex1_steps', inject='KSampler.2.steps', kind='n'),
        KnobRow(card='tex1_cfg', inject='KSampler.2.cfg', kind='n'),
        KnobRow(card='tex2_steps', inject='KSampler.3.steps', kind='n'),
        KnobRow(card='tex2_cfg', inject='KSampler.3.cfg', kind='n'),
        KnobRow(card='remesh_resolution', inject='RemeshMesh.0.resolution', kind='n'),
        KnobRow(card='decimate_faces', inject='DecimateMesh.0.target_face_count', kind='n'),
        KnobRow(card='smooth_angle', inject='MeshSmoothNormals.0.crease_angle', kind='n'),
        KnobRow(card='atlas_size', inject='UnwrapMesh.0.resolution', kind='n'),
        KnobRow(card='ao_size', inject='BakeAmbientOcclusion.0.resolution', kind='n'),
        KnobRow(card='normal_size', inject='BakeNormalMapFromMesh.0.resolution', kind='n'),
        KnobRow(card='struct_sampler', inject='KSampler.0.sampler_name', kind='s'),
        KnobRow(card='struct_scheduler', inject='KSampler.0.scheduler', kind='s'),
        KnobRow(card='shape_sampler', inject='KSampler.1.sampler_name', kind='s'),
        KnobRow(card='shape_scheduler', inject='KSampler.1.scheduler', kind='s'),
        KnobRow(card='tex1_sampler', inject='KSampler.2.sampler_name', kind='s'),
        KnobRow(card='tex1_scheduler', inject='KSampler.2.scheduler', kind='s'),
        KnobRow(card='tex2_sampler', inject='KSampler.3.sampler_name', kind='s'),
        KnobRow(card='tex2_scheduler', inject='KSampler.3.scheduler', kind='s'),
        KnobRow(card='sd3_shift', inject='ModelSamplingSD3.0.shift', kind='n'),
        KnobRow(card='rescale_struct', inject='RescaleCFG.0.multiplier', kind='n'),
        KnobRow(card='rescale_shape', inject='RescaleCFG.1.multiplier', kind='n'),
        KnobRow(card='override_struct', inject='CFGOverride.0.start_percent', kind='n'),
        KnobRow(card='override_shape', inject='CFGOverride.1.start_percent', kind='n'),
    )
